  ); }}//$myKernelCompile=new LittleKernelCompiler($haveToCompile);class LittleKernelCompilerHack extends LittleKernelCompiler{ function __construct(Array $haveToCompile) {  parent::__construct($haveToCompile); } public function hackCompile() {  return $this->compile(); }}?>